cat > /work/submit/planb64.cpp <<'EOF'
// PlanB64 -- offline FIB compiler and longest-prefix-match lookup tool.
//
// build  :: FIB -> canonical minimal change-point interval image
// lookup :: image + trace -> one "NEXT_HOP PREFIX_LENGTH" line per query
//
// The compiler reduces longest-prefix matching on the upper 64 address bits
// to a predecessor search over disjoint intervals.  For every FIB prefix we
// create the half-open event pair (start, +prefix) and (end+1, -prefix) and
// sweep them in coordinate order, keeping the longest active prefix.  Only
// coordinates where the winning (hop, length) pair changes become image rows.

#include <arpa/inet.h>

#include <algorithm>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <string>
#include <utility>
#include <vector>
#include <set>

namespace {

struct Row {
    uint64_t start;
    int64_t  hop;
    int      len;
};

struct Error {};

[[noreturn]] void fail() { throw Error{}; }

constexpr uint64_t MAXHOP = 4294967295ULL;

bool allDigits(const std::string& s) {
    if (s.empty()) return false;
    for (char c : s)
        if (c < '0' || c > '9') return false;
    return true;
}

// Parse an input decimal field: digits only, leading zeros allowed, value<=max.
bool parseInputUInt(const std::string& s, unsigned long long maxval,
                    unsigned long long& out) {
    if (!allDigits(s)) return false;
    unsigned __int128 v = 0;
    for (char c : s) {
        v = v * 10 + (unsigned)(c - '0');
        if (v > (unsigned __int128)maxval) return false;
    }
    out = (unsigned long long)v;
    return true;
}

// Strict canonical decimal for image fields: digits only, no leading zeros
// (except the single character "0"), value<=max.
bool parseCanonicalUInt(const std::string& s, unsigned long long maxval,
                        unsigned long long& out) {
    if (!allDigits(s)) return false;
    if (s.size() > 1 && s[0] == '0') return false;
    unsigned __int128 v = 0;
    for (char c : s) {
        v = v * 10 + (unsigned)(c - '0');
        if (v > (unsigned __int128)maxval) return false;
    }
    out = (unsigned long long)v;
    return true;
}

bool validHex16(const std::string& s, uint64_t& out) {
    if (s.size() != 16) return false;
    uint64_t v = 0;
    for (char c : s) {
        unsigned d;
        if (c >= '0' && c <= '9') d = (unsigned)(c - '0');
        else if (c >= 'a' && c <= 'f') d = (unsigned)(c - 'a' + 10);
        else return false;                 // uppercase or non-hex rejected
        v = (v << 4) | d;
    }
    out = v;
    return true;
}

// Split a raw input line on spaces / tabs / carriage returns.
void tokenize(const std::string& line, std::vector<std::string>& out) {
    out.clear();
    size_t i = 0, n = line.size();
    while (i < n) {
        char c = line[i];
        if (c == ' ' || c == '\t' || c == '\r') { ++i; continue; }
        size_t j = i;
        while (j < n && line[j] != ' ' && line[j] != '\t' && line[j] != '\r')
            ++j;
        out.emplace_back(line, i, j - i);
        i = j;
    }
}

// Parse a full 128-bit IPv6 address and return the upper 64 bits.
bool parseAddress(const std::string& s, uint64_t& key) {
    if (s.empty()) return false;
    if (s.find('/') != std::string::npos) return false; // no CIDR on addresses
    unsigned char bytes[16];
    if (inet_pton(AF_INET6, s.c_str(), bytes) != 1) return false;
    uint64_t k = 0;
    for (int i = 0; i < 8; ++i) k = (k << 8) | bytes[i];
    key = k;
    return true;
}

// ---------------- FIB compilation ----------------

struct Event {
    unsigned __int128 coord;  // change coordinate (<= 2^64-1)
    int type;                 // 0 = remove, 1 = add (removes sort first)
    int len;
    int64_t hop;
};

// Compile a FIB file into canonical rows (in memory).
std::vector<Row> compileFIB(const std::string& path) {
    std::ifstream in(path, std::ios::binary);
    if (!in) fail();

    std::vector<Event> events;
    std::set<std::pair<uint64_t, int>> seen;

    std::string line;
    std::vector<std::string> tok;
    unsigned long long records = 0;

    while (std::getline(in, line)) {
        if (line.size() > 256) fail();          // supported line-length limit
        tokenize(line, tok);
        if (tok.empty()) continue;              // blank line
        if (tok.size() != 2) fail();            // extra tokens
        ++records;
        if (records > 200000ULL) fail();        // FIB record limit

        const std::string& prefix = tok[0];
        size_t slash = prefix.find('/');
        if (slash == std::string::npos) fail();
        if (prefix.find('/', slash + 1) != std::string::npos) fail();
        if (slash == 0 || slash + 1 >= prefix.size()) fail();

        uint64_t key;
        if (!parseAddress(prefix.substr(0, slash), key)) fail();

        unsigned long long plen;
        if (!parseInputUInt(prefix.substr(slash + 1), 64, plen)) fail();
        int len = (int)plen;

        unsigned long long hopull;
        if (!parseInputUInt(tok[1], MAXHOP, hopull)) fail();
        int64_t hop = (int64_t)hopull;

        // Normalize: clear every host bit (lower 64 bits are always host bits
        // because len<=64; the key holds only the upper 64 bits anyway).
        if (len == 0) key = 0;
        else key &= (~0ULL << (64 - len));

        std::pair<uint64_t, int> id(key, len);
        if (!seen.insert(id).second) fail();    // duplicate normalized prefix

        uint64_t end;
        if (len == 0) {
            end = ~0ULL;
        } else {
            uint64_t size = (uint64_t)1 << (64 - len);
            end = key + size - 1;
        }

        unsigned __int128 s = (unsigned __int128)key;
        events.push_back(Event{s, 1, len, hop});
        unsigned __int128 stop = (unsigned __int128)end + 1;
        if (stop <= (unsigned __int128)~0ULL)
            events.push_back(Event{stop, 0, len, hop});
    }
    if (in.bad()) fail();

    std::sort(events.begin(), events.end(),
              [](const Event& a, const Event& b) {
                  if (a.coord != b.coord) return a.coord < b.coord;
                  return a.type < b.type;      // removes before adds
              });

    std::vector<Row> rows;
    int64_t activeHop[65];
    for (int i = 0; i <= 64; ++i) activeHop[i] = -1;

    auto winner = [&](int64_t& hop, int& len) {
        for (int l = 64; l >= 0; --l) {
            if (activeHop[l] != -1) { hop = activeHop[l]; len = l; return; }
        }
        hop = -1; len = -1;
    };
    auto applyGroup = [&](size_t i, size_t j) {
        for (size_t k = i; k < j; ++k) {
            const Event& e = events[k];
            if (e.type == 0) activeHop[e.len] = -1;
            else             activeHop[e.len] = e.hop;
        }
    };

    size_t idx = 0;
    const size_t ne = events.size();
    int64_t curHop = -1;
    int curLen = -1;

    if (ne == 0) {
        rows.push_back(Row{0, -1, -1});
        return rows;
    }

    if (events[0].coord == 0) {
        size_t j = 0;
        while (j < ne && events[j].coord == 0) ++j;
        applyGroup(0, j);
        idx = j;
        winner(curHop, curLen);
        rows.push_back(Row{0, curHop, curLen});
    } else {
        rows.push_back(Row{0, -1, -1});
        curHop = -1; curLen = -1;
    }

    while (idx < ne) {
        unsigned __int128 c = events[idx].coord;
        size_t j = idx;
        while (j < ne && events[j].coord == c) ++j;
        applyGroup(idx, j);
        idx = j;
        int64_t hop; int len;
        winner(hop, len);
        if (hop != curHop || len != curLen) {
            rows.push_back(Row{(uint64_t)c, hop, len});
            curHop = hop; curLen = len;
        }
    }

    if (rows.size() > 400001ULL) fail();
    return rows;
}

// ---------------- Image serialization ----------------

void appendHex16(std::string& out, uint64_t v) {
    static const char* hx = "0123456789abcdef";
    char buf[16];
    for (int i = 0; i < 16; ++i)
        buf[i] = hx[(v >> (4 * (15 - i))) & 0xF];
    out.append(buf, 16);
}

std::string serialize(const std::vector<Row>& rows) {
    std::string out;
    out.reserve(rows.size() * 34 + 32);
    out += "PLANB64 1\n";
    out += std::to_string(rows.size());
    out += '\n';
    for (const Row& r : rows) {
        appendHex16(out, r.start);
        out += ' ';
        out += std::to_string(r.hop);
        out += ' ';
        out += std::to_string(r.len);
        out += '\n';
    }
    return out;
}

void writeImage(const std::string& path, const std::string& data) {
    std::string tmp = path + ".tmp";
    {
        std::ofstream out(tmp, std::ios::binary | std::ios::trunc);
        if (!out) fail();
        out.write(data.data(), (std::streamsize)data.size());
        out.flush();
        if (!out) fail();
    }
    if (std::rename(tmp.c_str(), path.c_str()) != 0) {
        std::remove(tmp.c_str());
        fail();
    }
}

// ---------------- Image reader ----------------

void splitLines(const std::string& data, std::vector<std::string>& lines) {
    size_t start = 0;
    for (size_t i = 0; i < data.size(); ++i) {
        if (data[i] == '\n') {
            lines.emplace_back(data, start, i - start);
            start = i + 1;
        }
    }
    // data ends with '\n', so start == data.size(); no trailing partial line.
}

std::vector<Row> loadImage(const std::string& path) {
    std::ifstream in(path, std::ios::binary);
    if (!in) fail();
    std::string data((std::istreambuf_iterator<char>(in)),
                     std::istreambuf_iterator<char>());
    if (in.bad()) fail();
    if (data.empty()) fail();
    if (data.back() != '\n') fail();            // missing final newline

    std::vector<std::string> lines;
    splitLines(data, lines);
    if (lines.size() < 2) fail();
    if (lines[0] != "PLANB64 1") fail();

    unsigned long long count;
    if (!parseCanonicalUInt(lines[1], 400001, count)) fail();
    if (count == 0) fail();
    if (lines.size() != (size_t)(2 + count)) fail();   // mismatch / extra

    std::vector<Row> rows;
    rows.reserve((size_t)count);
    uint64_t prevKey = 0;
    bool first = true;

    for (size_t li = 2; li < lines.size(); ++li) {
        const std::string& L = lines[li];
        // Exactly three single-space separated fields, no leading/trailing
        // spaces (empty fields from doubled/edge spaces are rejected below).
        size_t p1 = L.find(' ');
        if (p1 == std::string::npos) fail();
        size_t p2 = L.find(' ', p1 + 1);
        if (p2 == std::string::npos) fail();
        if (L.find(' ', p2 + 1) != std::string::npos) fail();
        if (p1 == 0 || p2 == p1 + 1 || p2 + 1 >= L.size()) fail();

        std::string f0 = L.substr(0, p1);
        std::string f1 = L.substr(p1 + 1, p2 - p1 - 1);
        std::string f2 = L.substr(p2 + 1);

        uint64_t key;
        if (!validHex16(f0, key)) fail();

        int64_t hop;
        if (f1 == "-1") hop = -1;
        else {
            unsigned long long v;
            if (!parseCanonicalUInt(f1, MAXHOP, v)) fail();
            hop = (int64_t)v;
        }
        int len;
        if (f2 == "-1") len = -1;
        else {
            unsigned long long v;
            if (!parseCanonicalUInt(f2, 64, v)) fail();
            len = (int)v;
        }

        if ((hop == -1) != (len == -1)) fail();  // one-sided no-match
        if (hop >= 0 && (len < 0 || len > 64)) fail();
        if (hop < -1) fail();

        if (first) {
            if (key != 0) fail();                // first key must be zero
            first = false;
        } else {
            if (key <= prevKey) fail();          // strictly increasing
        }
        prevKey = key;

        if (!rows.empty()) {
            const Row& p = rows.back();
            if (p.hop == hop && p.len == len) fail();  // equal adjacent pairs
        }
        rows.push_back(Row{key, hop, len});
    }
    if (rows.empty()) fail();
    return rows;
}

// ---------------- Lookup ----------------

std::vector<uint64_t> loadTrace(const std::string& path) {
    std::ifstream in(path, std::ios::binary);
    if (!in) fail();
    std::vector<uint64_t> queries;
    std::string line;
    std::vector<std::string> tok;
    unsigned long long records = 0;
    while (std::getline(in, line)) {
        if (line.size() > 256) fail();
        tokenize(line, tok);
        if (tok.empty()) continue;
        if (tok.size() != 1) fail();             // one address per line
        uint64_t key;
        if (!parseAddress(tok[0], key)) fail();
        ++records;
        if (records > 1000000ULL) fail();
        queries.push_back(key);
    }
    if (in.bad()) fail();
    return queries;
}

void doLookup(const std::vector<Row>& rows, const std::vector<uint64_t>& queries) {
    std::string out;
    out.reserve(queries.size() * 8 + 16);
    for (uint64_t key : queries) {
        auto it = std::upper_bound(
            rows.begin(), rows.end(), key,
            [](uint64_t k, const Row& r) { return k < r.start; });
        --it;  // first row has start 0, so it is never begin()
        out += std::to_string(it->hop);
        out += ' ';
        out += std::to_string(it->len);
        out += '\n';
    }
    std::fwrite(out.data(), 1, out.size(), stdout);
    std::fflush(stdout);
}

bool parseBatchSize(const std::string& s, unsigned& out) {
    if (s.empty()) return false;
    unsigned long long v = 0;
    for (char c : s) {
        if (c < '0' || c > '9') return false;
        v = v * 10 + (unsigned)(c - '0');
        if (v > 100000) return false;
    }
    if (v < 1 || v > 256) return false;
    out = (unsigned)v;
    return true;
}

}  // namespace

int main(int argc, char** argv) {
    try {
        if (argc >= 2 && std::string(argv[1]) == "build") {
            if (argc != 4) fail();
            std::vector<Row> rows = compileFIB(argv[2]);
            std::string data = serialize(rows);
            writeImage(argv[3], data);
            return 0;
        }
        if (argc >= 2 && std::string(argv[1]) == "lookup") {
            if (argc < 5) fail();
            std::string mode = argv[4];
            if (mode == "scalar") {
                if (argc != 5) fail();
            } else if (mode == "batch") {
                if (argc != 6) fail();
                unsigned bs;
                if (!parseBatchSize(argv[5], bs)) fail();
            } else {
                fail();
            }
            std::vector<Row> rows = loadImage(argv[2]);
            std::vector<uint64_t> queries = loadTrace(argv[3]);
            doLookup(rows, queries);
            return 0;
        }
        fail();
    } catch (const Error&) {
        std::fputs("ERROR: invalid input or arguments\n", stderr);
        return 2;
    } catch (const std::exception&) {
        std::fputs("ERROR: failure\n", stderr);
        return 2;
    } catch (...) {
        std::fputs("ERROR: failure\n", stderr);
        return 2;
    }
}
